    /// <summary>Puts the shrine right after the special building, the Price of Loyalty order.</summary>
    /// <param name="buildings">The buildings without it.</param>
    /// <param name="index">Where the shrine goes.</param>
    /// <param name="version">The version of the map.</param>
    /// <returns>The order.</returns>
    private static IReadOnlyList<BuildingType> WithShrine(IReadOnlyList<BuildingType> buildings, int index, MapVersion version)
    {
        if (version == MapVersion.SuccessionWars)
        {
            return buildings;
        }

        List<BuildingType> result = [.. buildings];
        result.Insert(index, BuildingType.Shrine);

        return result;
    }
